import {spawn} from 'node:child_process';import {mkdtemp,rm} from 'node:fs/promises';import os from 'node:os';import path from 'node:path';
const profile=await mkdtemp(path.join(os.tmpdir(),'legendgirl-campanha-'));
const chrome=spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',['--headless=new','--mute-audio','--no-first-run','--no-default-browser-check','--autoplay-policy=no-user-gesture-required','--remote-debugging-port=9222','--user-data-dir='+profile,'about:blank'],{stdio:'ignore'});
try{for(let i=0;i<100;i++){try{await fetch('http://127.0.0.1:9222/json/version');break;}catch{}await new Promise(r=>setTimeout(r,100));}
for(const name of ['test:debug-phases:browser']){console.log('VALIDANDO',name);const code=await new Promise(resolve=>{const p=spawn('npm',['run','journal:qa','--',name],{stdio:'inherit'});p.once('exit',resolve);});if(code)console.log('FALHA PRESERVADA',name,code);}
}finally{chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
